import { type ReactNode, createContext, useContext, useMemo } from 'react'
import { useColorScheme } from 'react-native'
import { useControllableState } from '../hooks/useControllableState'
import type { ColorModePreference, ResolvedColorMode } from '../types'

export interface ColorModeContextValue {
  /** What the user picked: `light`, `dark` or follow the `system`. */
  colorMode: ColorModePreference
  /** The mode actually applied. */
  resolvedColorMode: ResolvedColorMode
  setColorMode: (mode: ColorModePreference) => void
}

const ColorModeContext = createContext<ColorModeContextValue | null>(null)

export interface ColorModeProviderProps {
  colorMode?: ColorModePreference
  defaultColorMode?: ColorModePreference
  onColorModeChange?: (mode: ColorModePreference) => void
  children: (resolved: ResolvedColorMode) => ReactNode
}

export function ColorModeProvider({
  colorMode: colorModeProp,
  defaultColorMode = 'system',
  onColorModeChange,
  children,
}: ColorModeProviderProps) {
  const system = useColorScheme()
  const [colorMode, setColorMode] = useControllableState<ColorModePreference>({
    value: colorModeProp,
    defaultValue: defaultColorMode,
    onChange: onColorModeChange,
  })
  const resolvedColorMode: ResolvedColorMode =
    colorMode === 'system' ? (system === 'dark' ? 'dark' : 'light') : colorMode

  const value = useMemo(
    () => ({ colorMode, resolvedColorMode, setColorMode }),
    [colorMode, resolvedColorMode, setColorMode],
  )

  return (
    <ColorModeContext.Provider value={value}>
      {children(resolvedColorMode)}
    </ColorModeContext.Provider>
  )
}

/** Read and change the light/dark/system preference from anywhere in the tree. */
export function useColorMode(): ColorModeContextValue {
  const context = useContext(ColorModeContext)
  if (!context) {
    throw new Error('[advui] useColorMode must be used inside <UniversalProvider>.')
  }
  return context
}

// Native has no global stylesheet; reduced motion is handled per component via `useReducedMotion`.
export function GlobalStyles() {
  return null
}

// Web-only global rules. React 19 hoists `<style href precedence>` into <head>
// (including during SSR), so no framework-specific wiring is needed.
const css = `
a.is_Button { text-decoration: none; }
@keyframes aui-spin { to { transform: rotate(360deg); } }
.aui-spinner { animation: aui-spin 0.8s linear infinite; }
@keyframes aui-pulse { 50% { opacity: 0.5; } }
.aui-skeleton { animation: aui-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  /* Loading indicators convey state, so keep them moving — just slower. */
  .aui-spinner {
    animation-duration: 1.6s !important;
    animation-iteration-count: infinite !important;
  }
}
`

export function GlobalStyles() {
  return (
    <style href="advui-global" precedence="default">
      {css}
    </style>
  )
}

import { IconProvider, type IconRegistry } from '@advui/icons'
import type { ReactNode } from 'react'
import { TamaguiProvider, type TamaguiInternalConfig, type TamaguiProviderProps } from 'tamagui'
import { Toaster, type ToasterProps } from '../components/toast/Toaster'
import type { ColorModePreference } from '../types'
import { ColorModeProvider } from './ColorMode'
import { GlobalStyles } from './GlobalStyles'

export interface UniversalProviderProps {
  /** Result of `createUniversalConfig()`. */
  config: TamaguiInternalConfig
  children: ReactNode
  /** Controlled color mode. Omit to let the provider manage it. */
  colorMode?: ColorModePreference
  /** Initial color mode when uncontrolled. Default: `system`. */
  defaultColorMode?: ColorModePreference
  onColorModeChange?: (mode: ColorModePreference) => void
  /** Swap or extend the icons used by `<Icon name="…" />` and components. */
  icons?: IconRegistry
  /** Options for the built-in toast viewport, or `false` to render your own `<Toaster />`. */
  toaster?: ToasterProps | false
  /** Skip Tamagui's runtime CSS injection when you ship a pre-generated stylesheet. */
  disableInjectCSS?: boolean
  /**
   * Native safe-area insets (e.g. from `useSafeAreaInsets()`). Overlays such
   * as toasts use them to stay clear of the notch and home indicator.
   */
  insets?: TamaguiProviderProps['insets']
}

/**
 * Root provider for Adv UI. Wraps Tamagui's provider and adds color-mode
 * management, reduced-motion handling, the icon registry and toasts.
 */
export function UniversalProvider({
  config,
  children,
  colorMode,
  defaultColorMode,
  onColorModeChange,
  icons,
  toaster = {},
  disableInjectCSS,
  insets,
}: UniversalProviderProps) {
  const content = (
    <>
      {children}
      {toaster === false ? null : <Toaster {...toaster} />}
    </>
  )

  return (
    <ColorModeProvider
      colorMode={colorMode}
      defaultColorMode={defaultColorMode}
      onColorModeChange={onColorModeChange}
    >
      {(resolved) => (
        <TamaguiProvider
          config={config}
          defaultTheme={resolved}
          disableInjectCSS={disableInjectCSS}
          insets={insets}
        >
          <GlobalStyles />
          {icons ? <IconProvider icons={icons}>{content}</IconProvider> : content}
        </TamaguiProvider>
      )}
    </ColorModeProvider>
  )
}

import type { UniversalConfig } from '@advui/theme'

// Registers Adv UI's tokens and themes with Tamagui so props like
// `backgroundColor="$primary"` and `padding="$4"` are type-checked.
declare module 'tamagui' {
  // Module augmentation requires an interface; the empty body is intentional.
  // eslint-disable-next-line @typescript-eslint/no-empty-object-type
  interface TamaguiCustomConfig extends UniversalConfig {}
}

export type ColorModePreference = 'light' | 'dark' | 'system'
export type ResolvedColorMode = 'light' | 'dark'
